import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_indexOfAny_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;



















    /**
     * This test targets the supplementary character (High Surrogate) logic.
     * The code has a specific branch for Character.isHighSurrogate(ch).
     * Note: The provided implementation has a potential bug in the loop condition (j <= searchLen)
     * which might cause ArrayIndexOutOfBoundsException if not careful, 
     * but we test the logic as provided.
     */
    @Test
    public void testIndexOfAny_SupplementaryCharacter_Match() {
        // U+1F600 (Grinning Face) is represented by high surrogate \uD83D and low surrogate \uDE00
        String emoji = "\uD83D\uDE00"; 
        char[] searchChars = new char[]{'\uD83D', '\uDE00'};

        // This tests the branch: if (i < csLast && j < searchLast && Character.isHighSurrogate(ch))
        assertEquals(0, StringUtils.indexOfAny(emoji, searchChars));
    }






}

