import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_indexOfAny_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;

























    @Test
    public void testIndexOfAny_HighSurrogateAtSearchEnd() {
        // Testing the boundary where j < searchLast is false
        String emoji = "\uD83D\uDE00";
        char[] searchChars = new char[]{'\uD83D'};
        // When ch is \uD83D, i=0, j=0. 
        // i < csLast (0 < 1) is true, but j < searchLast (0 < 0) is false.
        // It falls into the 'else' block and returns i.
        assertEquals(0, StringUtils.indexOfAny(emoji, searchChars));
    }
}
